#[cfg(kani)]
#[allow(non_snake_case)]
mod PCA_harness {
    use super::*;
    pub(super) fn PCA_count_reference(accounts: &[AccountInfo<'_>], expected: usize) -> ProgramResult {
        if accounts.len() != expected {
            return Err(if accounts.len() < expected {
                ProgramError::NotEnoughAccountKeys
            } else {
                ProgramError::InvalidArgument
            });
        }
        Ok(())
    }
    #[kani::proof_for_contract(super::require_exact_account_count)]
    fn PCA_count_contract() {
        let accounts: &[AccountInfo<'_>] = kani::any();
        let expected: usize = kani::any();
        let _ = require_exact_account_count(accounts, expected);
    }
}
